"use client";

import React, { useState } from "react";
import { Sparkles, ArrowRight, Heart } from "lucide-react";

export function ProductCardPremium() {
  const [liked, setLiked] = useState(false);

  return (
    <div className="w-full max-w-xs bg-card/45 backdrop-blur-xl border border-border/50 rounded-2xl shadow-xl select-none font-sans overflow-hidden text-foreground">
      <div className="p-4 relative">
        <div className="h-32 bg-secondary/20 rounded-xl border border-white/[0.04] mb-3 flex items-center justify-center relative">
          <Sparkles className="w-8 h-8 text-violet-400" />
          <button 
            onClick={() => setLiked(!liked)}
            className="absolute top-2 right-2 p-1.5 rounded-lg bg-secondary/50 hover:bg-secondary text-muted-foreground"
          >
            <Heart className={`w-3.5 h-3.5 ${liked ? "fill-red-400 text-red-400" : ""}`} />
          </button>
        </div>

        <div className="space-y-1">
          <span className="text-[9px] uppercase font-bold text-violet-400">Exclusive Series</span>
          <h4 className="text-sm font-black">Lux Studio Framework</h4>
          <p className="text-xs text-muted-foreground/60 leading-normal">Premium react libraries with HSL components.</p>
        </div>

        <div className="flex items-center justify-between mt-4 pt-3 border-t border-white/[0.04]">
          <span className="text-xs font-black">$299.00</span>
          <button className="px-3 py-1.5 bg-primary hover:brightness-110 text-white text-[10px] font-bold rounded-lg flex items-center gap-1">
            <span>Purchase</span>
            <ArrowRight className="w-3 h-3" />
          </button>
        </div>
      </div>
    </div>
  );
}
